/* СТАТИСТИКА ВЫДЕЛЕНИЯ. Панель обновляется на каждом ходе курсора
   («приВыделении», не чаще раза в 150 мс). Снимок книги плагину не нужен —
   «читает»: «ничего»: маленькую область он читает по запросу, а большую не
   читает вовсе, там итоги считает ядро прямо по хранилищу. Так один и тот же
   плагин работает и на десяти клетках, и на десяти миллионах. */

const ЧИСЛОМ = з => typeof з === 'number'
  ? з.toLocaleString('ru-RU', {maximumFractionDigits: 6}) : String(з);

async function Показать(){
  const в = книга.выделение;
  if(!в) return;
  const п = параметры({});
  const всего = (в.r2 - в.r1 + 1) * (в.c2 - в.c1 + 1);
  const предел = Math.max(0, +п.предел || 0);
  const л = лист(в.лист);
  const ряды = [['Область', в.лист + '!' + в.область], ['Клеток', ЧИСЛОМ(всего)]];

  if(всего <= предел){
    /* до предела читаем сами: так видно и текст, и пустые, и разные значения */
    const строки = await л.прочитать(в.область);
    let чисел = 0, текста = 0, пусто = 0, сумма = 0, мин = null, макс = null;
    const разные = п.разные ? new Set() : null;
    for(const р of строки) for(const з of р){
      if(з === null || з === undefined || з === ''){ пусто++; continue; }
      if(разные) разные.add(typeof з + ':' + з);
      if(typeof з === 'number'){
        чисел++; сумма += з;
        if(мин === null || з < мин) мин = з;
        if(макс === null || з > макс) макс = з;
      } else текста++;
    }
    ряды.push(['Чисел', ЧИСЛОМ(чисел)], ['Текста', ЧИСЛОМ(текста)], ['Пусто', ЧИСЛОМ(пусто)]);
    if(чисел) ряды.push(['Сумма', ЧИСЛОМ(сумма)], ['Среднее', ЧИСЛОМ(сумма / чисел)],
                        ['Минимум', ЧИСЛОМ(мин)], ['Максимум', ЧИСЛОМ(макс)]);
    if(разные) ряды.push(['Разных значений', ЧИСЛОМ(разные.size)]);
    ряды.push(['Как посчитано', 'по клеткам']);
  } else {
    /* больше предела — данные никуда не едут, считает ядро */
    const [сумма, среднее, мин, макс, чисел] = await Promise.all(
      ['СУММ', 'СРЗНАЧ', 'МИН', 'МАКС', 'СЧЁТ'].map(и => л.итог(и, в.область)));
    ряды.push(['Чисел', ЧИСЛОМ(чисел)], ['Сумма', ЧИСЛОМ(сумма)], ['Среднее', ЧИСЛОМ(среднее)],
              ['Минимум', ЧИСЛОМ(мин)], ['Максимум', ЧИСЛОМ(макс)],
              ['Как посчитано', 'итогами ядра: область больше ' + ЧИСЛОМ(предел) + ' клеток']);
  }
  панель.список('итоги', ряды);
}

/* Пункт меню на любой клетке — то же самое, но вслух */
async function Сказать(){
  await Показать();
  const в = книга.выделение;
  const с = await лист(в.лист).итог('СУММ', в.область);
  await диалог.сообщение(в.область + ': сумма ' + ЧИСЛОМ(с));
}
